function login(){userId=null;localStorage.removeItem(AUTH);sessionStorage.removeItem(AUTH);$('#app').innerHTML=`<main class="auth-shell"><section class="auth-brand"><div class="brandmark">V</div><h1>VERITAS CORE</h1><p>RBCIA Accounting Firm</p><p class="hero-summary">Clarity in every detail.<br>Your practice, connected.</p><div class="demo-account-title">DEMO ACCOUNTS · CHOOSE A ROLE</div><div class="demo-roles">${db.users.slice(0,3).map(u=>`<button class="btn" type="button" data-action="choose-role" data-id="${u.id}">${labelRole(u.role)}</button>`).join('')}</div><p class="subtext demo-note">Browser-only demo. Any nonempty password works.</p></section><section class="auth-card panel pad"><form id="login-form"><h2 class="modal-title">Welcome back</h2><p class="subtext">Sign in to your workspace.</p><div class="field"><label for="email">Email address</label><input class="input" id="email" name="email" type="email" required value="owner@demo.veritas.local"></div><div class="field"><label for="password">Password</label><input class="input" id="password" name="password" type="password" required value="demo"></div><label class="remember"><input type="checkbox" name="remember" checked> Remember me</label><button class="btn btn-primary" type="submit" style="width:100%">Sign in</button><button class="forgot-link" type="button" data-action="forgot">Forgot password?</button></form></section></main>`;$('#toasts').className='toasts'}
function stat(name,value,link,note=''){return `<div class="panel stat"><div class="stat-label">${esc(name)}</div><div class="stat-value">${value}</div><a href="#/${link}">${esc(note||'View details →')}</a></div>`}
function invoiceTotal(x){return x.items.reduce((n,i)=>n+Math.round(Number(i.qty)*Number(i.price)),0)+Number(x.tax||0)}
function paid(x){return x.payments.reduce((n,p)=>n+Number(p.amount),0)}
function balance(x){return Math.max(0,invoiceTotal(x)-paid(x))}
function invoiceStatus(x){if(x.status==='Draft'||x.status==='Cancelled')return x.status;if(balance(x)===0)return 'Paid';return x.due<today()?'Overdue':paid(x)?'Partially Paid':'Open'}
function completeness(c){let r=db.requirements.filter(x=>x.client===c.id);return {done:r.filter(x=>x.status==='Verified').length,total:r.length}}
function dashboard(){let cs=db.clients.filter(visibleClient),ds=scoped(db.documents),co=scoped(db.compliance),js=scoped(db.journals),inv=scoped(db.invoices),out=inv.reduce((n,x)=>n+(x.status==='Cancelled'?0:balance(x)),0),over=co.filter(x=>x.status!=='Filed'&&x.due<today()).length,soon=co.filter(x=>x.status!=='Filed'&&x.due>=today()&&x.due<=future(10)).length;return `<section class="hero"><div class="eyebrow">A CLEARER VIEW OF YOUR PRACTICE</div><h2>Welcome back, ${esc(me().name)}.</h2><div>${new Date().toLocaleDateString('en-PH',{weekday:'long',year:'numeric',month:'long',day:'numeric'})}</div><p>${over} overdue filings need attention. ${soon} more deadlines are approaching in the next 10 days.</p><button class="btn btn-gold" data-go="compliance">Review deadlines ↗</button></section><div class="toolbar"><h2 class="section-title">${esc(labelRole(me().role))} overview</h2><div class="actions"><button class="btn" data-create="clients">New client</button><button class="btn" data-create="documents">Add document</button><button class="btn" data-create="billing">New invoice</button></div></div><div class="grid stats">${stat(bookkeeper()?'Assigned active clients':'Active clients',cs.filter(x=>x.status==='Active').length,'clients',`${cs.length} total clients`)}${stat('Documents in progress',ds.filter(x=>['Submitted','Needs clarification'].includes(x.status)).length,'documents')}${stat('Due within 10 days',soon,'compliance')}${stat('Overdue filings',over,'monitoring')}</div><div class="grid stats">${stat('Pending onboarding',cs.filter(x=>x.status==='Pending').length,'onboarding')}${stat('Missing documents',scoped(db.requirements).filter(x=>x.status==='Missing').length,'missing')}${stat('Journals for review',js.filter(x=>x.status==='For Review').length,'ledger')}${stat('Outstanding invoices',money(out),'billing')}</div><div class="grid two"><section class="panel"><div class="panel-head"><div><h2 class="section-title">Compliance watch</h2><div class="subtext">Nearest unresolved filings</div></div><button class="btn btn-sm" data-go="compliance">View all</button></div>${table(['Client & requirement','Agency','Due date','Status'],co.filter(x=>x.status!=='Filed').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5).map(x=>[`<a href="#/compliance/${x.id}">${esc(x.requirement)}</a><div class="subtext">${esc(client(x.client)?.name)}</div>`,esc(x.agency),fmt(x.due),badge(x.due<today()?'Overdue':x.status)]))}</section><section class="panel pad"><h2 class="section-title">Billing snapshot</h2><div class="stat-value">${money(out)}</div><div class="subtext">Outstanding balance</div><p>${inv.filter(x=>invoiceStatus(x)==='Paid').length} paid · ${inv.filter(x=>balance(x)>0&&x.status!=='Draft').length} open</p><div class="progress"><span style="width:${Math.round(100*inv.filter(x=>invoiceStatus(x)==='Paid').length/Math.max(inv.length,1))}%"></span></div><p class="subtext">Collected: ${money(inv.reduce((n,x)=>n+paid(x),0))}<br>Total billed: ${money(inv.filter(x=>x.status!=='Cancelled').reduce((n,x)=>n+invoiceTotal(x),0))}</p><button class="btn" data-go="billing">Open billing</button></section></div><div class="grid three" style="margin-top:16px">${[['Recent clients',cs.slice(-5).reverse(),'clients','name'],['Recent documents',ds.slice(-5).reverse(),'documents','title'],['Recent invoices',inv.slice(-5).reverse(),'billing','number']].map(([title,items,m,k])=>`<section class="panel pad"><h2 class="section-title">${title}</h2><ul class="timeline">${items.map(x=>`<li><a href="#/${m}/${x.id}">${esc(x[k])}</a><div class="subtext">${esc(client(x.client)?.name||'')} ${badge(x.status)}</div></li>`).join('')}</ul></section>`).join('')}</div><section class="panel pad" style="margin-top:16px"><h2 class="section-title">Recent activity</h2><ul class="timeline">${db.audit.slice(0,6).map(x=>`<li>${esc(x.description)}<div class="subtext">${esc(staff(x.actor))} · ${fmt(x.date.slice(0,10))}</div></li>`).join('')||'<li>No recent activity yet.</li>'}</ul></section>`}
