function dataset(m){return {clients:db.clients.filter(visibleClient),documents:scoped(db.documents),requirements:scoped(db.requirements),'doc-templates':db.templates,missing:scoped(db.requirements).filter(x=>x.status!=='Verified'),onboarding:db.clients.filter(visibleClient),ledger:scoped(db.journals),vouchers:scoped(db.vouchers),compliance:scoped(db.compliance),monitoring:scoped(db.compliance).filter(x=>x.status!=='Filed'),billing:scoped(db.invoices),knowledge:db.articles.filter(x=>!bookkeeper()||x.status==='Published'||x.author===userId),notices:db.notices,accounts:db.accounts,templates:db.accountTemplates,users:db.users,audit:db.audit,notifications:db.notifications}[m]||[]}
function titleFor(m,x){return m==='clients'||m==='onboarding'?x.name:m==='documents'?x.title:m==='requirements'||m==='missing'?db.templates.find(t=>t.id===x.template)?.name:m==='ledger'?x.memo:m==='vouchers'?x.number:m==='compliance'||m==='monitoring'?x.requirement:m==='billing'?x.number:m==='knowledge'||m==='notices'?x.title:m==='accounts'?`${x.code} ${x.name}`:m==='templates'||m==='doc-templates'?x.name:m==='users'?x.name:m==='notifications'?x.text:m==='audit'?x.description:x.id}
