function listPage(m){let all=dataset(m),hasClient=!['clients','onboarding','knowledge','notices','accounts','templates','doc-templates','users','audit','notifications'].includes(m);let q=query.toLowerCase().trim();let arr=all.filter(x=>(!q||`${titleFor(m,x)} ${hasClient?client(x.client)?.name||'':''} ${fieldVal(m,x)}`.toLowerCase().includes(q))&&(!filter||statusFor(m,x)===filter));arr.sort((a,b)=>{let av=sort==='date'?(a.date||a.created||a.due||''):sort==='status'?statusFor(m,a):titleFor(m,a),bv=sort==='date'?(b.date||b.created||b.due||''):sort==='status'?statusFor(m,b):titleFor(m,b);return String(av).localeCompare(String(bv))});let size=Number(db.settings.pageSize)||10,pages=Math.max(1,Math.ceil(arr.length/size));page=Math.min(page,pages);let rows=arr.slice((page-1)*size,page*size).map(x=>{let r=[`<a href="#/${m}/${x.id}">${esc(titleFor(m,x))}</a>`,hasClient?esc(client(x.client)?.name||'—'):esc(fieldVal(m,x)),hasClient?esc(fieldVal(m,x)):esc(x.date?fmt(x.date):x.created?fmt(x.created):'—'),badge(statusFor(m,x)),`<button class="btn btn-sm" data-view="${m}:${x.id}">View</button>`];return r});let statuses=[...new Set(all.map(x=>statusFor(m,x)))].filter(Boolean).sort();let canCreate=!['missing','onboarding','monitoring','audit','notifications'].includes(m)&&!(m==='notices'&&bookkeeper())&&!(m==='compliance'&&bookkeeper())&&!(m==='doc-templates'&&bookkeeper());return `<div class="toolbar"><div><h2 class="section-title">${label(m)} directory</h2><div class="subtext">${all.length} authorized records · Demo data saved in this browser</div></div><div class="actions">${canCreate?`<button class="btn btn-primary" data-create="${m}">Add ${label(m).replace(/s$/,'')}</button>`:''}<button class="btn" data-action="export" data-module="${m}">Export CSV</button></div></div>${m==='requirements'?'<div class="notice">Document requirements link each client to the checklist templates. Verified items count toward onboarding.</div>':''}${m==='monitoring'?'<div class="notice warn">Submission deadlines use the configurable offset in Workspace settings. They are demo dates, not RBCIA policy.</div>':''}<section class="panel"><div class="filters"><input class="input" id="list-search" aria-label="Search records" placeholder="Search ${label(m).toLowerCase()}" value="${esc(query)}"><select id="list-filter" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option ${filter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="list-sort" aria-label="Sort records"><option value="name" ${sort==='name'?'selected':''}>Name</option><option value="date" ${sort==='date'?'selected':''}>Date</option><option value="status" ${sort==='status'?'selected':''}>Status</option></select></div>${table(['Record',hasClient?'Client':'Detail',hasClient?'Detail':'Date','Status','Open'],rows)}<div class="pagination"><span>Showing ${arr.length?((page-1)*size+1):0}–${Math.min(page*size,arr.length)} of ${arr.length}</span><div class="actions"><button class="btn btn-sm" data-page="${page-1}" ${page<=1?'disabled':''}>Previous</button><span>Page ${page} of ${pages}</span><button class="btn btn-sm" data-page="${page+1}" ${page>=pages?'disabled':''}>Next</button></div></div></section>`}
