 if(m==='requirements')body=clientField(x,preset)+select('template','Requirement template',db.templates.map(t=>[t.id,t.name]),x?.template)+input('due','Expected date',x?.due||future(7),'date')+select('status','Status',['Missing','Awaiting verification','Verified','Incomplete','Needs clarification'].map(s=>[s,s]),x?.status||'Missing');
 if(m==='ledger'){let cid=x?.client||preset||db.clients.find(visibleClient)?.id;body=clientField(x,preset)+input('date','Entry date',x?.date||today(),'date')+textarea('memo','Memo',x?.memo)+`<div class="wide"><div class="toolbar"><strong>Debit and credit lines</strong><button class="btn btn-sm" type="button" data-action="add-line">Add line</button></div><div id="journal-lines" class="lines">${(x?.lines||[{account:`a1000-${cid}`,debit:0,credit:0},{account:`a4000-${cid}`,debit:0,credit:0}]).map(l=>lineForm(l,cid)).join('')}</div><p class="subtext" id="line-totals">Drafts may be unbalanced. Submission requires equal positive totals.</p></div>`}
 if(m==='vouchers')body=clientField(x,preset)+select('type','Voucher type',['JV','CV','CR','CD'].map(s=>[s,s]),x?.type||'JV')+input('date','Date',x?.date||today(),'date')+input('payee','Payee / received from',x?.payee)+input('amount','Amount (PHP)',x?x.amount/100:'','number')+textarea('description','Description',x?.description)+select('journal','Linked journal',[['','None'],...scoped(db.journals).map(j=>[j.id,`${j.id} · ${j.memo}`])],x?.journal||'');
  if(m==='compliance')body=clientField(x,preset)+input('requirement','Requirement',x?.requirement)+input('agency','Agency',x?.agency||'BIR')+input('due','Filing deadline',x?.due||future(14),'date')+`<div class="field"><label for="f-submissionDue">Client submission deadline (optional override)</label><input class="input" id="f-submissionDue" name="submissionDue" type="date" value="${x?.submissionManual?esc(x.submissionDue):''}"><small class="subtext">Leave empty for the calculated date: 10 calendar days before filing.</small></div>`+textarea('submissionReason','Override reason',x?.submissionReason||'')+select('staff','Assigned bookkeeper',db.users.filter(u=>u.role==='bookkeeper').map(u=>[u.id,u.name]),x?.staff)+select('status','Preparation status',['Pending','In preparation','Ready'].map(s=>[s,s]),x?.status||'Pending');
 if(m==='billing')body=clientField(x,preset)+input('date','Invoice date',x?.date||today(),'date')+input('due','Due date',x?.due||future(30),'date')+`<div class="wide"><div class="toolbar"><strong>Invoice items</strong><button class="btn btn-sm" type="button" data-action="add-item">Add item</button></div><div id="invoice-items" class="lines">${(x?.items||[{description:'Accounting services',qty:1,price:0}]).map(itemForm).join('')}</div></div>`+input('tax','Tax amount (PHP)',x?(x.tax/100):0,'number');
