function notifications(){let data=db.notifications.filter(n=>!bookkeeper()||!['users','audit','workspace'].includes(n.route));return `<div class="toolbar"><h2 class="section-title">Notification center</h2><button class="btn" data-action="read-all">Mark all read</button></div><section class="panel">${table(['Message','Date','Status','Action'],data.map(n=>[`<a href="#/${esc(n.route)}">${esc(n.text)}</a>`,fmt(n.date),badge(n.read?'Read':'Unread'),n.read?'—':`<button class="btn btn-sm" data-flow="read:${n.id}">Mark read</button>`]))}</section>`}
