function years(){return `<div class="notice warn">Accounting year and period creation or closing is unavailable in the original web interface. These demo periods are displayed for context only.</div><section class="panel"><div class="panel-head"><h2 class="section-title">Accounting years and periods</h2></div>${table(['Year','Period','Status'],db.periods.map(p=>[esc(p.year),new Date(p.year,p.month-1,1).toLocaleDateString('en-PH',{month:'long'}),badge(p.status)]))}</section>`}
function postedLines(clientId){return db.journals.filter(j=>j.status==='Posted'&&(!clientId||j.client===clientId)&&visibleClient(client(j.client))).flatMap(j=>j.lines.map(l=>({...l,journal:j.id,client:j.client,date:j.date,memo:j.memo})))}
