function reportPicker(m){let id=new URLSearchParams(location.hash.split('?')[1]||'').get('client')||'';return `<div class="toolbar"><h2 class="section-title">${label(m)}</h2><div class="actions"><select id="report-client" aria-label="Filter client"><option value="">All authorized clients</option>${opts(db.clients.filter(visibleClient),id)}</select><button class="btn" data-action="print">Print</button><button class="btn" data-action="export" data-module="${m}">Export CSV</button></div></div>`}
