function financial(){let cid=chosenClient(),rows=trial(cid),sumDebit=rows.reduce((n,a)=>n+Math.max(0,a.net),0),sumCredit=rows.reduce((n,a)=>n+Math.max(0,-a.net),0),assets=rows.filter(a=>a.type==='Asset').reduce((n,a)=>n+a.net,0),liabilities=rows.filter(a=>a.type==='Liability').reduce((n,a)=>n-a.net,0),equity=rows.filter(a=>a.type==='Equity').reduce((n,a)=>n-a.net,0),revenue=rows.filter(a=>a.type==='Revenue').reduce((n,a)=>n-a.net,0),expenses=rows.filter(a=>a.type==='Expense').reduce((n,a)=>n+a.net,0),profit=revenue-expenses;return reportPicker('financial')+`<div class="grid stats">${stat('Trial balance debits',money(sumDebit),'general')}${stat('Trial balance credits',money(sumCredit),'general')}${stat('Net income',money(profit),'financial')}${stat('Assets',money(assets),'financial')}</div><div class="grid two"><section class="panel"><div class="panel-head"><h2 class="section-title">Trial Balance</h2></div>${table(['Account','Debit balance','Credit balance'],rows.filter(a=>a.net!==0).map(a=>[esc(a.code+' · '+a.name),money(Math.max(0,a.net)),money(Math.max(0,-a.net))]))}<div class="panel-head"><strong>Totals</strong><strong>${money(sumDebit)} = ${money(sumCredit)}</strong></div></section><section class="panel pad"><h2 class="section-title">Income Statement</h2>${detailsList([['Revenue',money(revenue)],['Expenses',money(expenses)],['Net income',money(profit)]])}<h2 class="section-title" style="margin-top:25px">Balance Sheet</h2>${detailsList([['Assets',money(assets)],['Liabilities',money(liabilities)],['Equity',money(equity)],['Current profit',money(profit)],['Liabilities + equity + profit',money(liabilities+equity+profit)]])}${Math.abs(assets-(liabilities+equity+profit))>1?'<p class="notice bad">Balance sheet does not reconcile.</p>':'<p class="notice">Balance sheet reconciles.</p>'}</section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><h2 class="section-title">Accounts Ledger</h2></div>${table(['Code','Account','Type','Net balance'],rows.map(a=>[esc(a.code),esc(a.name),esc(a.type),money(Math.abs(a.net))]))}</section>`}
